const p=$input.first().json||{};
const ex=p.execution||{}; const wf=p.workflow||{}; const er=ex.error||p.error||p.trigger?.error||{};
const msg=String(er.message||er.description||'Unknown error').slice(0,800);
const root=String(ex.retryOf||ex.id||'unknown');
return [{json:{incident_key:`${wf.id||'workflow'}:${root}`,root_execution_id:root,last_execution_id:String(ex.id||root),workflow_id:String(wf.id||''),workflow_name:String(wf.name||'Unknown workflow'),failed_node:String(ex.lastNodeExecuted||er.node?.name||''),error_message:msg,error_stack:String(er.stack||'').slice(0,1500),execution_url:String(ex.url||''),execution_mode:String(ex.mode||''),retry_of:String(ex.retryOf||''),seen_at:new Date().toISOString()}}];

const x=$input.first().json; const s=(x.error_message+' '+x.error_stack).toLowerCase();
let c='unknown', max=0, delay=0, auto=false;
if(/429|too many requests|rate.?limit/.test(s)){c='rate_limit';max=3;delay=300;auto=true;}
else if(/etimedout|econnreset|socket hang up| 502 | 503 | 504 |service unavailable|bad gateway|gateway timeout/.test(s)){c='transient';max=3;delay=60;auto=true;}
else if(/ 401 | 403 |unauthori|forbidden|permission/.test(s)){c='auth';}
else if(/ 400 |invalid input|validation|schema|malformed/.test(s)){c='validation';}
else if(/business validation|manual correction|required business/.test(s)){c='business';}
else if(/out of memory|heap|concurrency|stalled|worker/.test(s)){c='resource';}
else if(/dependency|upstream|downstream/.test(s)){c='dependency';max=2;delay=300;auto=true;}
return [{json:{...x,error_class:c,max_attempts:max,auto_retry:auto,base_delay_seconds:delay}}];

const x=$('Classify Failure').first().json; const old=$input.first().json||{};
const attempts=Number(old.attempt_count||0); const alreadyAlerted=String(old.alert_sent||'no')==='yes';
const canRetry=x.auto_retry && attempts < x.max_attempts;
const schedule=[60,300,900]; const d=x.error_class==='rate_limit'?[300,900,1800][Math.min(attempts,2)]:(schedule[Math.min(attempts,2)]||900);
const retryAt=canRetry?new Date(Date.now()+d*1000).toISOString():'';
const status=canRetry?'queued':'escalated';
const next_action=canRetry?`Automatic retry scheduled at ${retryAt}`:'Human review required; automatic retry disabled/exhausted.';
return [{json:{...x,attempt_count:attempts,max_attempts:x.max_attempts,status,retry_at:retryAt,alert_sent:alreadyAlerted?'yes':'no',next_action,first_seen_at:old.first_seen_at||x.seen_at,last_seen_at:x.seen_at}}];
